<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class mlogistics extends CI_Controller {    public function __construct() {        parent::__construct();        $this->load->model(CNFCOMPANY . "mlogisticsmodel");        $this->load->model(CNFCOMPANY . "mforwardingagentmodel");        $this->load->model(CNFCOMPANY . "mclearingagentmodel");        $this->load->model(CNFCOMPANY . "mimportermodel");        $this->load->helper('xssclean');        fnIfCheckUserLoggedIn();        $this->limit = LIMITPERPAGE;        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $this->companyid = $ArrUserLoggedInfo['companyid'];        $this->userid = $ArrUserLoggedInfo['id'];    }    public function addEditForagent() {        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '');        $VarId = base64_decode(urldecode($this->uri->segment(4)));        $ArrData['Edit'] = $this->uri->segment(5);        if (is_numeric($VarId)) {            $ArrResults = $this->mforwardingagentmodel->fnGetInfo('', '', $VarId, $this->companyid);            $ArrData['ArrBasicInfo'] = $ArrResults[0];            $ArrData['VarId'] = $ArrResults[0]['id'];        } else {        }        $this->load->view(CNFCOMPANY . 'addEditForagent', $ArrData);    }    public function addEditClragent() {        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '');        $VarId = base64_decode(urldecode($this->uri->segment(4)));        $ArrData['Edit'] = $this->uri->segment(5);        if (is_numeric($VarId)) {            $ArrResults = $this->mclearingagentmodel->fnGetInfo('', '', $VarId, $this->companyid);            $ArrData['ArrBasicInfo'] = $ArrResults[0];            $ArrData['VarId'] = $ArrResults[0]['id'];        } else {        }        $this->load->view(CNFCOMPANY . 'addEditClragent', $ArrData);    }    public function addEditImporter() {        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '');        $VarId = base64_decode(urldecode($this->uri->segment(4)));        $ArrData['Edit'] = $this->uri->segment(5);        if (is_numeric($VarId)) {            $ArrResults = $this->mimportermodel->fnGetInfo('', '', $VarId, $this->companyid);            $ArrData['ArrBasicInfo'] = $ArrResults[0];            $ArrData['VarId'] = $ArrResults[0]['id'];        } else {        }        $this->load->view(CNFCOMPANY . 'addEditImporter', $ArrData);    }    public function addedit() {        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '');        $VarId = base64_decode(urldecode($this->uri->segment(4)));        $ArrData['Edit'] = $this->uri->segment(5);        if (is_numeric($VarId)) {            $ArrResults = $this->mforwardingagentmodel->fnGetInfo('', '', $VarId, $this->companyid);            $ArrData['ArrBasicInfo'] = $ArrResults[0];            $ArrData['VarId'] = $ArrResults[0]['id'];        } else {        }        $this->load->view(CNFCOMPANY . 'addeditlogistics', $ArrData);    }    public function updateForAgent() {        $VarFAgent = xssclean($this->input->post('fa'));        $VarStatus = xssclean($this->input->post('s'));        $VarId = xssclean($this->input->post('id'));        if ($VarFAgent <> '') {            $ArrUpdateData = array('id' => $VarId, 'companyid' => $this->companyid, 'logistic' => $VarFAgent, 'type' => 1,                'status' => $VarStatus, 'updatedby' => $this->userid, 'dateupdated' => date('Y-m-d H:i:s'));            if (empty($VarId)) {                $ArrUpdateData['datecreated'] = date('Y-m-d H:i:s');            }            $ArrResult = $this->mforwardingagentmodel->saveInfo($ArrUpdateData);        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg'] = 'Invalid Input';        }        echo json_encode($ArrResult);    }    public function updateClrAgent() {        $VarCAgent = xssclean($this->input->post('ca'));        $VarStatus = xssclean($this->input->post('s'));        $VarId = xssclean($this->input->post('id'));        if ($VarCAgent <> '') {            $ArrUpdateData = array('id' => $VarId, 'companyid' => $this->companyid, 'logistic' => $VarCAgent, 'type' => 2,                'status' => $VarStatus, 'updatedby' => $this->userid, 'dateupdated' => date('Y-m-d H:i:s'));            if (empty($VarId)) {                $ArrUpdateData['datecreated'] = date('Y-m-d H:i:s');            }            $ArrResult = $this->mclearingagentmodel->saveInfo($ArrUpdateData);        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg'] = 'Invalid Input';        }        echo json_encode($ArrResult);    }    public function updateImporter() {        $VarImporter = xssclean($this->input->post('imp'));        $VarStatus = xssclean($this->input->post('s'));        $VarId = xssclean($this->input->post('id'));        if ($VarImporter <> '') {            $ArrUpdateData = array('id' => $VarId, 'companyid' => $this->companyid, 'logistic' => $VarImporter, 'type' => 3,                'status' => $VarStatus, 'updatedby' => $this->userid, 'dateupdated' => date('Y-m-d H:i:s'));            if (empty($VarId)) {                $ArrUpdateData['datecreated'] = date('Y-m-d H:i:s');            }            $ArrResult = $this->mimportermodel->saveInfo($ArrUpdateData);        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg'] = 'Invalid Input';        }        echo json_encode($ArrResult);    }    public function updateInfo() {        $VarConShipExporter = xssclean($this->input->post('cse'));        $VarFAgent = xssclean($this->input->post('fa'));        $VarCAgent = xssclean($this->input->post('ca'));        $VarConsignee = xssclean($this->input->post('cnee'));        $VarImporter = xssclean($this->input->post('i'));        $VarStatus = xssclean($this->input->post('s'));        $VarId = xssclean($this->input->post('id'));        if ($VarConShipExporter <> '') {            $ArrUpdateData = array('id' => $VarId, 'companyid' => $this->companyid,                'consignorexporter' => $VarConShipExporter, 'forwardingagent' => $VarFAgent, 'clearingagent' => $VarCAgent,                'importer' => $VarImporter, 'consignee' => $VarConsignee, 'status' => $VarStatus, 'updatedby' => $this->userid, 'dateupdated' => date('Y-m-d H:i:s'));            if ($VarId == '' || $VarId == 0) {                $ArrUpdateData['datecreated'] = date('Y-m-d H:i:s');            }            $ArrResult = $this->mforwardingagentmodel->saveInfo($ArrUpdateData);        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg'] = 'Invalid Input';        }        echo json_encode($ArrResult);    }    public function importer() {        $VarFrom = xssclean($this->input->post('rfrom'));        $VarImporter = xssclean($this->input->post('imp'));        $VarStatus = xssclean($this->input->post('s'));        $clickedColumnId = xssclean($this->input->post('columnId'));        $newsortorder = xssclean($this->input->post('sortorder'));        $ArrDbCols = array('logistic', 'i.status', 'u.contactname', 'i.dateupdated');        if ($VarFrom == 1) {            $VarURLSegment = 4;            $this->load->library('pagination');            $config['base_url'] = base_url() . CNFCOMPANY . 'mlogistics/importer';            $config['total_rows'] = $this->mimportermodel->fnCount($VarImporter, $VarStatus);            $config['per_page'] = $this->limit;            $config['uri_segment'] = $VarURLSegment;            $offset = $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby = "i.dateupdated";            $sortorder = "desc";            if ($clickedColumnId <> '' && $newsortorder <> '') {                if (array_key_exists($clickedColumnId, $ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrList = $this->mimportermodel->fnList($VarImporter, $VarStatus, $this->limit, $offset, $sortby, $sortorder)->result();            $data['pagination'] = $this->pagination->create_linkswithajax('Importer');            $i = 0;            $ArrFnlList = array();            $ArrStatus = unserialize(ARRSTATUS);            foreach ($ArrList as $Obj) {                $ArrFnlList[$i]['id'] = $Obj->id;                $ArrFnlList[$i]['imp'] = $Obj->logistic;                $ArrFnlList[$i]['ub'] = $Obj->contactname;                $ArrFnlList[$i]['s'] = $ArrStatus[$Obj->status];                $ArrFnlList[$i]['du'] = date('d-m-Y H:i:s', strtotime($Obj->dateupdated));                $i = $i + 1;            }            echo json_encode(array('errcode' => 1, 'cn' => $config['total_rows'], 'ct' => $i, 're' => $ArrFnlList, 'pa' => base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY . 'manageImporter');        }    }    public function clearingAgent() {        $VarFrom = xssclean($this->input->post('rfrom'));        $VarClearingagent = xssclean($this->input->post('ca'));        $VarStatus = xssclean($this->input->post('s'));        $clickedColumnId = xssclean($this->input->post('columnId'));        $newsortorder = xssclean($this->input->post('sortorder'));        $ArrDbCols = array('logistic', 'c.status', 'u.contactname', 'c.dateupdated');        if ($VarFrom == 1) {            $VarURLSegment = 4;            $this->load->library('pagination');            $config['base_url'] = base_url() . CNFCOMPANY . 'mlogistics/clearingAgent';            $config['total_rows'] = $this->mclearingagentmodel->fnCount($VarClearingagent, $VarStatus);            $config['per_page'] = $this->limit;            $config['uri_segment'] = $VarURLSegment;            $offset = $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby = "c.dateupdated";            $sortorder = "desc";            if ($clickedColumnId <> '' && $newsortorder <> '') {                if (array_key_exists($clickedColumnId, $ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrList = $this->mclearingagentmodel->fnList($VarClearingagent, $VarStatus, $this->limit, $offset, $sortby, $sortorder)->result();            $data['pagination'] = $this->pagination->create_linkswithajax('clearingAgent');            $i = 0;            $ArrFnlList = array();            $ArrStatus = unserialize(ARRSTATUS);            foreach ($ArrList as $Obj) {                $ArrFnlList[$i]['id'] = $Obj->id;                $ArrFnlList[$i]['ca'] = $Obj->logistic;                $ArrFnlList[$i]['ub'] = $Obj->contactname;                $ArrFnlList[$i]['s'] = $ArrStatus[$Obj->status];                $ArrFnlList[$i]['du'] = date('d-m-Y H:i:s', strtotime($Obj->dateupdated));                $i = $i + 1;            }            echo json_encode(array('errcode' => 1, 'cn' => $config['total_rows'], 'ct' => $i, 're' => $ArrFnlList, 'pa' => base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY . 'manageClragent');        }    }    public function forwardingAgent() {        $VarFrom = xssclean($this->input->post('rfrom'));        $VarForwardingagent = xssclean($this->input->post('fa'));        $VarStatus = xssclean($this->input->post('s'));        $clickedColumnId = xssclean($this->input->post('columnId'));        $newsortorder = xssclean($this->input->post('sortorder'));        $ArrDbCols = array('logistic', 'f.status', 'u.contactname', 'f.dateupdated');        if ($VarFrom == 1) {            $VarURLSegment = 4;            $this->load->library('pagination');            $config['base_url'] = base_url() . CNFCOMPANY . 'mlogistics/forwardingAgent';            $conf